/** The signed-in Server browser image's build context (signed-in/), file name to content. */
export const SIGNED_IN_FILES: Readonly<Record<string, string>> = {
  "Dockerfile": "# Signed-in Server browser image for the browser-prompt plugin: neko (https://github.com/m1k1o/neko,\n# Apache-2.0) with Chromium, a desktop the owner can watch and take over over WebRTC, plus the\n# plugin's overrides. Built locally by the plugin only after the owner's explicit choice in its\n# settings (the base image is about 1.5 GB) and tagged with a hash of this build context, never\n# `latest`. The base image is pinned by digest: neko 3.2.0 with Chromium 155.\n# Overrides:\n#   - chromium.conf: Chromium's own sandbox on, DevTools protocol on 127.0.0.1:9222 inside the\n#     container only (for the run agent's Playwright MCP, which shares this container's network\n#     namespace), session restore, no crash bubble; no --bwsi (guest mode would not keep logins).\n#   - chromium-start.sh: removes stale profile locks and starts Chromium with the filtering proxy\n#     sidecar as its only way out (also for loopback), refusing to start without it.\n#   - policies.json: neko's policy without the forced Google extensions, with DevTools allowed\n#     (needed for the protocol), cookies kept (neko ships session-only cookies), no password\n#     manager, autofill, sync, sign-in, downloads, file pickers, extensions, metrics reporting or\n#     background mode, standard Safe Browsing, and every internal page blocked (chrome://*,\n#     chrome-untrusted://*, chrome-search://*, chrome-extension://*, devtools://*, view-source:,\n#     about:*, javascript:, data:, file://) except about:blank and chrome://newtab (which opens about:blank), so neither\n#     the agent nor a page can read history, settings or the list of signed-in sites there.\n#   - viewer.css: neko's web client shows its on-screen keyboard button only below 769 px, so an\n#     iPad could tap but not type; this stylesheet (linked from neko's index.html) shows it on touch\n#     screens of any width. viewer.css and viewer.js are served as bp-viewer-<content hash>.css/.js,\n#     so a browser never uses a cached copy from an older image.\n#   - viewer.js (linked from neko's index.html, before neko's own deferred bundle) plus a one-line\n#     hook in neko's onKeyDown: on touch devices a tap on the video focuses neko's key-capture\n#     textarea without the on-screen keyboard (so an iPad's hardware keyboard types right after\n#     Request controls), no autocorrect/autocapitalize/spell check on it, and Shift is held around\n#     capitals and shifted symbols that arrive without it (on-screen keyboard text, dictation).\n#     The build fails when the hook's anchor is not found exactly once.\nFROM ghcr.io/m1k1o/neko/chromium:3.2.0@sha256:270face8b8111e639744fb7bcdbbf0deed227900bb89d58b2f8adfc12af8c41e\n\nCOPY chromium.conf /etc/neko/supervisord/chromium.conf\nCOPY chromium-start.sh /usr/local/bin/chromium-start.sh\nCOPY policies.json /etc/chromium/policies/managed/policies.json\nRUN chmod 0755 /usr/local/bin/chromium-start.sh && chmod 0644 /etc/neko/supervisord/chromium.conf /etc/chromium/policies/managed/policies.json\nCOPY viewer.css /var/www/assets/bp-viewer.css\nCOPY viewer.js /var/www/assets/bp-viewer.js\nRUN cd /var/www/assets \\\n  && css=\"bp-viewer-$(sha256sum bp-viewer.css | cut -c1-12).css\" && js=\"bp-viewer-$(sha256sum bp-viewer.js | cut -c1-12).js\" \\\n  && mv bp-viewer.css \"$css\" && mv bp-viewer.js \"$js\" && chmod 0644 \"$css\" \"$js\" \\\n  && sed -i \"s#</head>#<link rel=\\\"stylesheet\\\" href=\\\"./assets/$css\\\"><script src=\\\"./assets/$js\\\"></script></head>#\" /var/www/index.html \\\n  && grep -q \"href=\\\"./assets/$css\\\"\" /var/www/index.html \\\n  && grep -q \"src=\\\"./assets/$js\\\"\" /var/www/index.html \\\n  && bundle=$(ls /var/www/assets/index-*.js) && [ \"$(echo \"$bundle\" | wc -l)\" = 1 ] \\\n  && [ \"$(grep -o 'this\\.client\\.input\\.key(e,!0),ze(e))' \"$bundle\" | wc -l)\" = 1 ] \\\n  && sed -i 's/this\\.client\\.input\\.key(e,!0),ze(e))/(window.bpKeyDown?window.bpKeyDown(this,e):this.client.input.key(e,!0)),ze(e))/' \"$bundle\" \\\n  && grep -q 'window.bpKeyDown(this,e)' \"$bundle\"\n",
  "chromium-start.sh": "#!/bin/sh\n# Starts Chromium for the browser-prompt signed-in Server browser (see chromium.conf). Removes the\n# profile locks a previous container left (the container's host name changes on every start), and\n# sends every request through the filtering proxy sidecar (BP_PROXY), loopback included, so pages\n# can reach neither this container's own services (neko, the DevTools port) nor private, tailnet or\n# host addresses. Without a valid BP_PROXY it does not start Chromium at all.\n# Bitwarden (only in the image variant built after the owner's consent, see signed-in-bitwarden/):\n# the variant force-installs it by policy, with this install's extension id (the daemon's signing\n# key, kept across images and pins). This script records the ids of the Bitwarden builds the profile\n# has seen (.bp-bitwarden-ids) and, on every start, removes what is left of every one not installed\n# now: all of them when Bitwarden is off, an old one after the id changed (data directories, the\n# shared extension databases, preference entries). (Chromium\n# itself uninstalls a force-installed extension once the policy no longer names it, and the plugin\n# clears the extension origins' storage through DevTools after the start.)\nPROFILE=/home/neko/.config/chromium\nPIN=/opt/bitwarden/browser-prompt-pin.json\nIDS=\"$PROFILE/.bp-bitwarden-ids\"\nDBS=\"$PROFILE/.bp-bitwarden-dbs-cleared\"\n# The first 0.23.0 builds loaded Bitwarden with its store id: a stale build where it left traces.\nLEGACY_ID=nngceckbapebfimnlniiiahkandclblb\nrm -f \"$PROFILE/SingletonLock\" \"$PROFILE/SingletonCookie\" \"$PROFILE/SingletonSocket\"\nif ! printf '%s' \"${BP_PROXY:-}\" | grep -Eq '^http://(bp-si-[0-9a-f]{8}-proxy|[0-9]{1,3}(\\.[0-9]{1,3}){3}):[0-9]{1,5}$'; then\n  echo \"browser-prompt: BP_PROXY is missing or not http://<stack proxy or ipv4>:<port>; refusing to start Chromium without the proxy\" >&2\n  sleep 10\n  exit 1\nfi\nCURRENT=\"\"\nif [ -f \"$PIN\" ]; then\n  CURRENT=$(grep -oE '\"id\": *\"[a-p]{32}\"' \"$PIN\" | grep -oE '[a-p]{32}')\n  if [ -n \"$CURRENT\" ] && ! grep -qx \"$CURRENT\" \"$IDS\" 2>/dev/null; then printf '%s\\n' \"$CURRENT\" >> \"$IDS\"; fi\n  # The installed build is not stale: forget that its shared databases were cleared once, so they are\n  # cleared again if it ever becomes stale later (turned off, a new id).\n  if [ -n \"$CURRENT\" ] && grep -qx \"$CURRENT\" \"$DBS\" 2>/dev/null; then\n    { grep -vx \"$CURRENT\" \"$DBS\" || true; } > \"$DBS.bp-tmp\" && mv -f \"$DBS.bp-tmp\" \"$DBS\"\n  fi\nfi\nif [ \"$LEGACY_ID\" != \"$CURRENT\" ] && ! grep -qx \"$LEGACY_ID\" \"$IDS\" 2>/dev/null; then\n  if [ -e \"$PROFILE/Default/Local Extension Settings/$LEGACY_ID\" ] || grep -q \"$LEGACY_ID\" \"$PROFILE/Default/Preferences\" 2>/dev/null; then printf '%s\\n' \"$LEGACY_ID\" >> \"$IDS\"; fi\nfi\nif [ -f \"$IDS\" ]; then\n  STALE=\"\"\n  for id in $(grep -xE '[a-p]{32}' \"$IDS\"); do\n    [ \"$id\" = \"$CURRENT\" ] && continue\n    STALE=\"$STALE $id\"\n    for dir in \"$PROFILE\"/Default \"$PROFILE\"/Profile*; do\n      [ -d \"$dir\" ] || continue\n      rm -rf \"$dir/Local Extension Settings/$id\" \"$dir/Sync Extension Settings/$id\" \"$dir/Managed Extension Settings/$id\" \\\n        \"$dir/Storage/ext/$id\" \"$dir/Extensions/$id\" \"$dir/IndexedDB/chrome-extension_${id}_0.indexeddb.leveldb\" \\\n        \"$dir/IndexedDB/chrome-extension_${id}_0.indexeddb.blob\" \"$dir/File System/chrome-extension_${id}_0\"\n    done\n  done\n  # Chromium's shared extension databases (state, rules, dynamic scripts) are keyed by extension id;\n  # Bitwarden is the only extension besides Chromium's own components, which rebuild their entries.\n  # Only on the first start after a build became stale (not on every start).\n  NEW_STALE=\"\"\n  for id in $STALE; do grep -qx \"$id\" \"$DBS\" 2>/dev/null || NEW_STALE=\"$NEW_STALE $id\"; done\n  if [ -n \"$NEW_STALE\" ]; then\n    for dir in \"$PROFILE\"/Default \"$PROFILE\"/Profile*; do\n      [ -d \"$dir\" ] && rm -rf \"$dir/Extension State\" \"$dir/Extension Rules\" \"$dir/Extension Scripts\"\n    done\n    for id in $NEW_STALE; do printf '%s\\n' \"$id\" >> \"$DBS\"; done\n  fi\n  # Their entries in Chromium's preferences (settings, uninstall records, shortcuts, MACs), before Chromium reads them.\n  if [ -n \"$STALE\" ] && command -v python3 >/dev/null 2>&1; then\n    python3 -I -c '\nimport json, os, sys\nstale = set(sys.argv[2:])\ndef names(v):\n    return isinstance(v, str) and (v in stale or any((\"chrome-extension://\" + s) in v for s in stale))\ndef clean(value):\n    if isinstance(value, dict):\n        # Drop entries named after a stale build, and records that point at one (keyboard shortcuts:\n        # {\"extension\": id, ...}), so Chromium does not bring them back.\n        # Also keys that name one: content settings use \"chrome-extension://<id>,*\".\n        return {k: clean(v) for k, v in value.items() if k not in stale and not names(k) and not names(v) and not (isinstance(v, dict) and any(names(x) for x in v.values()))}\n    if isinstance(value, list):\n        return [clean(v) for v in value if not names(v)]\n    return value\nfor root, dirs, files in os.walk(sys.argv[1]):\n    if root.count(os.sep) - sys.argv[1].count(os.sep) > 1:\n        continue\n    for name in (\"Preferences\", \"Secure Preferences\"):\n        if name not in files:\n            continue\n        path = os.path.join(root, name)\n        try:\n            data = json.load(open(path))\n        except Exception:\n            continue\n        cleaned = clean(data)\n        if cleaned != data:\n            with open(path + \".bp-tmp\", \"w\") as out:\n                json.dump(cleaned, out)\n            os.replace(path + \".bp-tmp\", path)\n' \"$PROFILE\" $STALE || true\n  fi\nfi\nexec /usr/bin/chromium \"$@\" --proxy-server=\"$BP_PROXY\" --proxy-bypass-list=\"<-loopback>\"\n",
  "chromium.conf": "[program:chromium]\nenvironment=HOME=\"/home/%(ENV_USER)s\",USER=\"%(ENV_USER)s\",DISPLAY=\"%(ENV_DISPLAY)s\"\ncommand=/usr/local/bin/chromium-start.sh\n  --disable-gpu-sandbox\n  --remote-debugging-port=9222\n  --remote-debugging-address=127.0.0.1\n  --window-position=0,0\n  --display=%(ENV_DISPLAY)s\n  --user-data-dir=/home/neko/.config/chromium\n  --no-first-run\n  --start-maximized\n  --disable-file-system\n  --disable-gpu\n  --disable-software-rasterizer\n  --disable-dev-shm-usage\n  --disable-session-crashed-bubble\n  --restore-last-session\n  --disable-quic\n  --no-pings\n  --disable-component-update\n  --disable-domain-reliability\n  --disable-breakpad\n  --disable-sync\n  --disable-features=WebUIOmniboxPopup,WebUIOmniboxFullPopup,WebUIOmniboxAimPopup\n  --force-webrtc-ip-handling-policy=disable_non_proxied_udp\n  --webrtc-ip-handling-policy=disable_non_proxied_udp\nstopsignal=INT\nstopwaitsecs=20\nautorestart=true\npriority=800\nuser=%(ENV_USER)s\nstdout_logfile=/var/log/neko/chromium.log\nstdout_logfile_maxbytes=10MB\nstdout_logfile_backups=1\nredirect_stderr=true\n\n[program:openbox]\nenvironment=HOME=\"/home/%(ENV_USER)s\",USER=\"%(ENV_USER)s\",DISPLAY=\"%(ENV_DISPLAY)s\"\ncommand=/usr/bin/openbox --config-file /etc/neko/openbox.xml\nautorestart=true\npriority=300\nuser=%(ENV_USER)s\nstdout_logfile=/var/log/neko/openbox.log\nstdout_logfile_maxbytes=10MB\nstdout_logfile_backups=1\nredirect_stderr=true\n",
  "policies.json": "{\n  \"AutofillAddressEnabled\": false,\n  \"AutofillCreditCardEnabled\": false,\n  \"BrowserSignin\": 0,\n  \"DefaultNotificationsSetting\": 2,\n  \"DeveloperToolsAvailability\": 1,\n  \"EditBookmarksEnabled\": false,\n  \"FullscreenAllowed\": true,\n  \"IncognitoModeAvailability\": 1,\n  \"SyncDisabled\": true,\n  \"AutoplayAllowed\": true,\n  \"BrowserAddPersonEnabled\": false,\n  \"BrowserGuestModeEnabled\": false,\n  \"DefaultPopupsSetting\": 2,\n  \"DownloadRestrictions\": 3,\n  \"AllowFileSelectionDialogs\": false,\n  \"PromptForDownloadLocation\": false,\n  \"BookmarkBarEnabled\": false,\n  \"PasswordManagerEnabled\": false,\n  \"BrowserLabsEnabled\": false,\n  \"CommandLineFlagSecurityWarningsEnabled\": false,\n  \"DefaultCookiesSetting\": 1,\n  \"MetricsReportingEnabled\": false,\n  \"SafeBrowsingProtectionLevel\": 1,\n  \"BackgroundModeEnabled\": false,\n  \"NewTabPageLocation\": \"about:blank\",\n  \"URLBlocklist\": [\n    \"file://*\",\n    \"chrome://*\",\n    \"chrome-untrusted://*\",\n    \"chrome-search://*\",\n    \"chrome-extension://*\",\n    \"devtools://*\",\n    \"view-source:*\",\n    \"about:*\",\n    \"javascript://*\",\n    \"javascript:*\",\n    \"data:*\"\n  ],\n  \"URLAllowlist\": [\n    \"about:blank\",\n    \"chrome://newtab\"\n  ],\n  \"ExtensionInstallBlocklist\": [\n    \"*\"\n  ]\n}\n",
  "viewer.css": "/* browser-prompt: neko's client shows its on-screen keyboard button (and the take-control button on\n   the video) only on screens up to 768 px wide (`phone:block hidden`), so on an iPad (834 px and\n   wider) the owner could tap but never type. Touch screens of any width get them too. neko renders\n   the keyboard button only on touch devices (no fine pointer, no hover), so this changes nothing\n   with a mouse or trackpad. */\n@media (pointer: coarse) and (min-width: 769px) {\n  .phone\\:block {\n    display: block;\n  }\n}\n",
  "viewer.js": "// browser-prompt: keyboard fixes for neko's web client in the owner's viewer (iPad, iPhone, Safari).\n// Loaded from neko's index.html (a classic script at the end of <head>, so it runs before neko's\n// deferred module bundle). neko takes keys only from the hidden <textarea> over the video (after a\n// <canvas>). On touch devices neko never focuses it: its tap handler cancels the touch (so the tap\n// does not focus it either) and it focuses on hover only without touch, so after \"Request\n// controls\" a hardware keyboard (an iPad's Magic Keyboard) typed into nothing; only neko's keyboard\n// button focused it, and that opens the on-screen keyboard.\n//   - Touch devices: every tap or click on the video focuses the textarea with inputmode=\"none\" (keys\n//     from a hardware keyboard, no on-screen keyboard); when control arrives, it is focused too\n//     unless something else (the chat) has focus. neko's keyboard button switches it to\n//     inputmode=\"text\" (and re-focuses it) so the on-screen keyboard opens as before.\n//   - No autocorrect, autocapitalize, spell check or writing suggestions on it: iOS must not alter\n//     what is typed (passwords).\n//   - Capitals and shifted symbols: neko sends the character's keysym without Shift when the browser\n//     reports none (the on-screen keyboard's text input, dictation, Safari's insertText), and the\n//     remote desktop then types the unshifted key (\"T\" became \"t\"). bpKeyDown, called from neko's\n//     onKeyDown (patched in the Dockerfile), holds Shift around such a key unless Shift, Caps Lock\n//     (for letters), Ctrl, Alt or Meta is down already, or neko's key state cannot be read. Known\n//     limit: neko never reports the remote desktop's Caps Lock (it only sends the local one when a\n//     mouse enters the video), so with the remote Caps Lock on, a capital from the on-screen keyboard\n//     comes out lowercase.\n(() => {\n  \"use strict\";\n  const SHIFT_L = 0xffe1;\n  const SHIFT_R = 0xffe2;\n  // Characters on a shifted key of the US layout (the remote desktop's layout).\n  const SHIFTED = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ~!@#$%^&*()_+{}|:\"<>?';\n  const touch = navigator.maxTouchPoints > 0 || \"ontouchstart\" in window;\n  // Caps Lock and Ctrl/Alt/Meta as the last key event reported them.\n  let capsLock = false;\n  let otherModifier = false;\n  // Keysyms that make a key a shortcut: Control, Meta, Alt, Super (left and right), AltGr, Mode_switch.\n  const SHORTCUT_MODIFIERS = [0xffe3, 0xffe4, 0xffe7, 0xffe8, 0xffe9, 0xffea, 0xffeb, 0xffec, 0xfe03, 0xff7e];\n\n  /** neko's key-capture textarea (the one right after the overlay canvas), or null. */\n  const capture = () => document.querySelector(\"canvas + textarea\");\n\n  function prepare(input) {\n    if (input.dataset.bpKeyboard) return;\n    input.dataset.bpKeyboard = \"1\";\n    input.setAttribute(\"autocapitalize\", \"off\");\n    input.setAttribute(\"autocorrect\", \"off\");\n    input.setAttribute(\"autocomplete\", \"off\");\n    input.setAttribute(\"writingsuggestions\", \"false\");\n    input.spellcheck = false;\n    if (touch) input.inputMode = \"none\";\n    // Back to \"no on-screen keyboard\" once it closes (neko's button, or iOS hiding it).\n    input.addEventListener(\"blur\", () => {\n      if (touch) input.inputMode = \"none\";\n    });\n  }\n\n  function focusSilently(input) {\n    if (document.activeElement === input) return;\n    if (touch && input.inputMode !== \"text\") input.inputMode = \"none\";\n    input.focus({ preventScroll: true });\n  }\n\n  // A tap or click on the video: capture phase, before neko's handler (which stops the event).\n  const onPointer = (event) => {\n    const input = capture();\n    if (!touch || !input || event.target !== input) return;\n    prepare(input);\n    focusSilently(input);\n  };\n  window.addEventListener(\"touchend\", onPointer, true);\n  window.addEventListener(\"pointerup\", onPointer, true);\n\n  // neko's keyboard button: open the on-screen keyboard even when a tap focused the textarea\n  // silently (re-focus with inputmode=\"text\"; neko's click handler then focuses it).\n  const onKeyboardButton = (event) => {\n    const button = event.target instanceof Element ? event.target.closest(\"[data-testid=keyboard-toggle]\") : null;\n    const input = capture();\n    if (!button || !input || input.inputMode === \"text\") return;\n    prepare(input);\n    if (document.activeElement === input) input.blur();\n    input.inputMode = \"text\";\n  };\n  window.addEventListener(\"pointerdown\", onKeyboardButton, true);\n  window.addEventListener(\"touchstart\", onKeyboardButton, true);\n  window.addEventListener(\"mousedown\", onKeyboardButton, true);\n\n  // Caps Lock (and Ctrl/Alt/Meta) as the hardware keyboard reports it.\n  const onKey = (event) => {\n    if (typeof event.getModifierState === \"function\") capsLock = event.getModifierState(\"CapsLock\");\n    otherModifier = !!(event.ctrlKey || event.altKey || event.metaKey);\n  };\n  window.addEventListener(\"keydown\", onKey, true);\n  window.addEventListener(\"keyup\", onKey, true);\n\n  // The textarea appears when neko attaches its overlay; the keyboard button appears (on touch\n  // devices) when the owner gets control: focus the textarea then, so keys work without a tap.\n  let hadControl = false;\n  new MutationObserver(() => {\n    const input = capture();\n    if (input) prepare(input);\n    if (!touch) return;\n    const control = !!document.querySelector(\"[data-testid=keyboard-toggle]\");\n    if (control && !hadControl && input) {\n      const active = document.activeElement;\n      const busy = active && active !== input && (active.matches(\"input, textarea, select, [contenteditable]\") || active.isContentEditable);\n      if (!busy) focusSilently(input);\n    }\n    hadControl = control;\n  }).observe(document.documentElement, { childList: true, subtree: true });\n\n  /** Called by neko's onKeyDown instead of client.input.key(keysym, true). */\n  window.bpKeyDown = (overlay, keysym) => {\n    const input = overlay.client.input;\n    // neko's Guacamole keyboard (overlay.keyboard, `pressed`: keysym -> true while down). Without it\n    // the Shift state is unknown: send the key as neko would.\n    const pressed = overlay.keyboard?.pressed;\n    const known = pressed !== null && typeof pressed === \"object\";\n    const char = keysym > 0x20 && keysym < 0x7f ? String.fromCharCode(keysym) : \"\";\n    const letter = char >= \"A\" && char <= \"Z\";\n    const shift =\n      known &&\n      char !== \"\" &&\n      SHIFTED.includes(char) &&\n      !pressed[SHIFT_L] &&\n      !pressed[SHIFT_R] &&\n      !(letter && capsLock) &&\n      !otherModifier &&\n      !SHORTCUT_MODIFIERS.some((modifier) => pressed[modifier]);\n    if (!shift) return input.key(keysym, true);\n    input.key(SHIFT_L, true);\n    try {\n      input.key(keysym, true);\n    } finally {\n      input.key(SHIFT_L, false);\n    }\n  };\n})();\n",
};

/** The Bitwarden variant's build context (signed-in-bitwarden/), file name to content. */
export const SIGNED_IN_BITWARDEN_FILES: Readonly<Record<string, string>> = {
  "Dockerfile": "# Bitwarden variant of the browser-prompt signed-in Server browser image. Built by the plugin only\n# after the owner's explicit two-press consent in its settings (Signed-in Server browser ›\n# Bitwarden), on top of the plugin's own signed-in image (BASE_IMAGE, built from signed-in/), and\n# tagged with a hash of both build contexts, never `latest`.\n#   - install-bitwarden.py downloads the Bitwarden Password Manager release pinned in bitwarden.json\n#     from Bitwarden's GitHub releases, refuses it unless size and SHA-256 match, packs it unchanged\n#     into a CRX with this install's key (stable id), and puts the CRX and a local\n#     update manifest (file://, the same version) read-only in /opt/bitwarden.\n#   - policy-overlay.json plus the install script: Chromium force-installs exactly that extension\n#     from the local manifest (it never updates it from anywhere) and blocks every other one\n#     (ExtensionInstallBlocklist \"*\", developer mode off, types and install sources locked, no\n#     external extensions, the Chrome Web Store blocked); chrome-extension:// pages are not blocked\n#     by URL (Bitwarden's inline menu frames use per-session dynamic ids no allowlist entry can\n#     name; the agent is kept off them by the plugin's filters); Chromium's password manager and\n#     autofill stay off; DevTools stay allowed for the plugin's lock check (never the agent's).\n# The extension's signing key is this install's (made once by the plugin, kept in its state\n# directory): it comes in only as a BuildKit secret for the install step, never as a build argument,\n# a file of the context or a layer. BITWARDEN_ID is the id the plugin expects from it.\nARG BASE_IMAGE\nFROM ${BASE_IMAGE}\nARG BITWARDEN_ID\nCOPY bitwarden.json policy-overlay.json install-bitwarden.py /tmp/bp-bitwarden/\nRUN --mount=type=secret,id=bitwarden-key,required=true BITWARDEN_ID=\"${BITWARDEN_ID}\" python3 -I /tmp/bp-bitwarden/install-bitwarden.py /tmp/bp-bitwarden && rm -rf /tmp/bp-bitwarden\n",
  "bitwarden.json": "{\n  \"version\": \"2026.11.0\",\n  \"url\": \"https://github.com/bitwarden/clients/releases/download/browser-v2026.11.0/bit-dist-chrome-2026.11.0.zip\",\n  \"sha256\": \"07cf19b8f79e649005fdeee67c85d3cf31c735449a01a37a5b9f0287732605a5\",\n  \"size\": 33808971\n}\n",
  "install-bitwarden.py": "# Installs the pinned Bitwarden Password Manager extension into the browser-prompt signed-in image\n# (see Dockerfile). Runs once at image build time, only after the owner's explicit two-press consent\n# in the plugin's settings. Python's standard library plus the image's own Chromium.\n#   1. Downloads the release zip named in bitwarden.json from Bitwarden's GitHub releases (https only,\n#      also on redirects) and refuses it unless its size and SHA-256 match the pin.\n#   2. Extracts it (regular files only, no absolute or .. paths) and checks the manifest: the pinned\n#      version, Manifest V3, no update_url. Nothing in it is changed.\n#   3. Packs it into a CRX with Chromium itself, signed with this install's key: the plugin makes it\n#      once and keeps it in its state directory; the build gets it only as a BuildKit secret\n#      (/run/secrets/bitwarden-key, mounted for this step only, never in a layer), so the extension's\n#      id stays the same across images and pins and Bitwarden's local data survives them. The id must\n#      be the one the plugin expects (BITWARDEN_ID). /opt/bitwarden then holds only the CRX, a local\n#      update manifest (file://, the same version: Chromium never updates it from anywhere) and the pin\n#      record, root-owned and read-only.\n#   4. Applies policy-overlay.json to Chromium's managed policy and force-installs exactly that id\n#      from the local update manifest; every other extension stays blocked (ExtensionInstallBlocklist\n#      \"*\"). Force-installed, Bitwarden can reload itself (it does after every lock); an extension\n#      loaded with --load-extension cannot (it disappears until the browser restarts).\nimport hashlib, io, json, os, shutil, stat, struct, subprocess, sys, urllib.request, zipfile\n\nhere = sys.argv[1]\npin = json.load(open(os.path.join(here, \"bitwarden.json\")))\noverlay = json.load(open(os.path.join(here, \"policy-overlay.json\")))\ntarget = \"/opt/bitwarden\"\nwork = \"/tmp/bp-bitwarden-build\"\nsource = os.path.join(work, \"bitwarden\")\nkey_secret = \"/run/secrets/bitwarden-key\"\nexpected_id = os.environ.get(\"BITWARDEN_ID\", \"\")\nif len(expected_id) != 32 or any(c not in \"abcdefghijklmnop\" for c in expected_id):\n    sys.exit(\"refusing: BITWARDEN_ID is missing or not an extension id\")\nif not os.path.isfile(key_secret):\n    sys.exit(\"refusing: the signing key secret is missing (the plugin passes it with docker build --secret)\")\npolicy_file = \"/etc/chromium/policies/managed/policies.json\"\n\nprefix = \"https://github.com/bitwarden/clients/releases/download/browser-v%s/\" % pin[\"version\"]\nif not pin[\"url\"].startswith(prefix) or not pin[\"url\"].endswith(\".zip\"):\n    sys.exit(\"refusing: the pinned URL is not a Bitwarden browser release zip on GitHub\")\n\nclass HttpsOnly(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        if not newurl.startswith(\"https://\"):\n            raise urllib.error.URLError(\"refusing a redirect away from https\")\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\n\nopener = urllib.request.build_opener(HttpsOnly)\nwith opener.open(urllib.request.Request(pin[\"url\"], headers={\"User-Agent\": \"browser-prompt-image-build\"}), timeout=300) as response:\n    data = response.read(pin[\"size\"] + 1)\nif len(data) != pin[\"size\"]:\n    sys.exit(\"refusing: the download is %d bytes, the pin says %d\" % (len(data), pin[\"size\"]))\ndigest = hashlib.sha256(data).hexdigest()\nif digest != pin[\"sha256\"]:\n    sys.exit(\"refusing: SHA-256 %s does not match the pin %s\" % (digest, pin[\"sha256\"]))\n\ntry:\n    os.makedirs(source)\n    with zipfile.ZipFile(io.BytesIO(data)) as archive:\n        for info in archive.infolist():\n            name = info.filename\n            if name.startswith(\"/\") or \"\\\\\" in name or \"..\" in name.split(\"/\"):\n                sys.exit(\"refusing: unsafe path in the archive: %r\" % name)\n            mode = (info.external_attr >> 16) & 0o170000\n            if mode and mode not in (stat.S_IFREG, stat.S_IFDIR):\n                sys.exit(\"refusing: not a regular file in the archive: %r\" % name)\n            path = os.path.join(source, name)\n            if name.endswith(\"/\"):\n                os.makedirs(path, exist_ok=True)\n                continue\n            os.makedirs(os.path.dirname(path), exist_ok=True)\n            with open(path, \"wb\") as out:\n                out.write(archive.read(info))\n\n    manifest = json.load(open(os.path.join(source, \"manifest.json\"), encoding=\"utf-8-sig\"))\n    if manifest.get(\"version\") != pin[\"version\"] or manifest.get(\"manifest_version\") != 3:\n        sys.exit(\"refusing: unexpected manifest version\")\n    if \"update_url\" in manifest or \"key\" in manifest:\n        sys.exit(\"refusing: the release zip carries an update_url or a key\")\n\n    # Pack with the image's Chromium and this install's key (read from the secret; Chromium writes no\n    # key file when it is given one, and any key file next to the CRX is removed anyway).\n    crx_file = source + \".crx\"\n    key_file = source + \".pem\"\n    try:\n        subprocess.run(\n            [\"chromium\", \"--headless=new\", \"--no-sandbox\", \"--user-data-dir=\" + os.path.join(work, \"profile\"), \"--pack-extension=\" + source, \"--pack-extension-key=\" + key_secret],\n            check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=300,\n        )\n        if not os.path.exists(crx_file):\n            sys.exit(\"refusing: Chromium did not pack the extension\")\n        crx = open(crx_file, \"rb\").read()\n    finally:\n        if os.path.exists(key_file):\n            os.remove(key_file)\n    if crx[:4] != b\"Cr24\" or struct.unpack(\"<I\", crx[4:8])[0] != 3:\n        sys.exit(\"refusing: not a CRX3 file\")\n\n    def varint(b, i):\n        r = s = 0\n        while True:\n            c = b[i]; i += 1; r |= (c & 0x7f) << s; s += 7\n            if not c & 0x80:\n                return r, i\n\n    def fields(b):\n        i, out = 0, []\n        while i < len(b):\n            k, i = varint(b, i)\n            if k & 7 == 2:\n                n, i = varint(b, i); out.append((k >> 3, b[i:i + n])); i += n\n            else:\n                v, i = varint(b, i); out.append((k >> 3, v))\n        return out\n\n    header = crx[12:12 + struct.unpack(\"<I\", crx[8:12])[0]]\n    crx_id = [v for f, v in fields([v for f, v in fields(header) if f == 10000][0]) if f == 1][0]\n    ext_id = \"\".join(chr(97 + (b >> 4)) + chr(97 + (b & 15)) for b in crx_id)\n    # The packed archive holds exactly the release's files.\n    with zipfile.ZipFile(io.BytesIO(crx[12 + len(header):])) as packed, zipfile.ZipFile(io.BytesIO(data)) as release:\n        want = {i.filename: release.read(i) for i in release.infolist() if not i.filename.endswith(\"/\")}\n        got = {i.filename: packed.read(i) for i in packed.infolist() if not i.filename.endswith(\"/\")}\n        if want != got:\n            sys.exit(\"refusing: the packed extension differs from the release\")\n\n    if ext_id != expected_id:\n        sys.exit(\"refusing: the packed extension's id %s is not the expected %s\" % (ext_id, expected_id))\n    os.makedirs(target)\n    shutil.copyfile(crx_file, os.path.join(target, \"bitwarden.crx\"))\n    with open(os.path.join(target, \"updates.xml\"), \"w\") as out:\n        out.write(\n            \"<?xml version='1.0' encoding='UTF-8'?>\\n\"\n            \"<gupdate xmlns='http://www.google.com/update2/response' protocol='2.0'>\\n\"\n            \"  <app appid='%s'><updatecheck codebase='file:///opt/bitwarden/bitwarden.crx' version='%s' /></app>\\n\"\n            \"</gupdate>\\n\" % (ext_id, pin[\"version\"])\n        )\n    with open(os.path.join(target, \"browser-prompt-pin.json\"), \"w\") as out:\n        json.dump({\"version\": pin[\"version\"], \"sha256\": digest, \"id\": ext_id, \"url\": pin[\"url\"]}, out)\n    for name in os.listdir(target):\n        os.chmod(os.path.join(target, name), 0o644)\n    os.chmod(target, 0o755)\nfinally:\n    # The work directory (the unpacked release, Chromium's packing profile) never stays in the image.\n    shutil.rmtree(work, ignore_errors=True)\n\npolicy = json.load(open(policy_file))\npolicy.update(overlay[\"set\"])\n# Bitwarden's inline menu and notification frames use per-session dynamic ids\n# (chrome-extension://<random>/overlay/...), which no allowlist entry can name: extension pages are\n# not blocked by URL. Every other extension is blocked, and the agent's access to extension pages is\n# refused by the plugin's DevTools and MCP filters.\nfor name, values in overlay[\"drop\"].items():\n    policy[name] = [v for v in policy.get(name, []) if v not in values]\nfor name, values in overlay[\"append\"].items():\n    policy[name] = list(policy.get(name, [])) + [v for v in values if v not in policy.get(name, [])]\npolicy[\"ExtensionInstallAllowlist\"] = [ext_id]\npolicy[\"ExtensionInstallForcelist\"] = [\"%s;file:///opt/bitwarden/updates.xml\" % ext_id]\nwith open(policy_file, \"w\") as out:\n    json.dump(policy, out, indent=2)\nos.chmod(policy_file, 0o644)\nprint(\"installed Bitwarden %s as %s (sha256 %s)\" % (pin[\"version\"], ext_id, digest))\n",
  "policy-overlay.json": "{\n  \"set\": {\n    \"ExtensionInstallBlocklist\": [\n      \"*\"\n    ],\n    \"ExtensionAllowedTypes\": [\n      \"extension\"\n    ],\n    \"ExtensionInstallSources\": [],\n    \"BlockExternalExtensions\": true,\n    \"ExtensionDeveloperModeSettings\": 1,\n    \"DeveloperToolsAvailability\": 1,\n    \"PasswordManagerEnabled\": false,\n    \"AutofillAddressEnabled\": false,\n    \"AutofillCreditCardEnabled\": false\n  },\n  \"drop\": {\n    \"URLBlocklist\": [\n      \"chrome-extension://*\"\n    ]\n  },\n  \"append\": {\n    \"URLBlocklist\": [\n      \"chromewebstore.google.com\",\n      \"chrome.google.com/webstore\"\n    ]\n  }\n}\n",
};
